/**
 * Memory Journal MCP Server - `adversarial-audit-code-quality` prompt definition.
 * [INTENT] Extracted from `adversarial.ts` (L1) so the long detector catalog can evolve without
 * pushing the shared prompt module past the 500-line ceiling.
 */

import type { InternalPromptDef } from './index.js'
import {
    AUDIT_PROMPT_REVISION,
    buildAuditPromptDefinition,
    buildSharedAuditPreamble,
} from './adversarial-audit-factory.js'

export const CODE_QUALITY_PROMPT_REVISION = AUDIT_PROMPT_REVISION

const SCAN_METHOD_1 = `     \`\`\`powershell
     $skip = @('.git','vendor','third_party','node_modules','dist','coverage','build','.next','out','.wrangler','.turbo','.output','.svelte-kit','.test-output')
     $n = 0
     $over = 0
     function Walk($dir, [bool]$inSkills = $false) {
       if (-not (Test-Path -LiteralPath $dir)) { return }
       foreach ($item in (Get-ChildItem -LiteralPath $dir -Force)) {
         if ($skip -contains $item.Name) { continue }
         if ($item.Attributes -band [System.IO.FileAttributes]::ReparsePoint) { continue }
         if ($item.PSIsContainer) { Walk $item.FullName ($inSkills -or $item.Name -eq 'skills'); continue }
         if (($item.Name -cmatch '\\.(ts|tsx|js|mjs|cjs)$' -or ($inSkills -and $item.Name -cmatch '\\.md$')) -and $item.Name -cnotmatch '\\.(test|spec|bench)\\.' -and $item.Name -cnotmatch '\\.d\\.ts$') {
           $script:n++
           $parts = [System.IO.File]::ReadAllText($item.FullName) -split '\\r?\\n'
           $lines = $parts.Length
           if ($lines -gt 0 -and $parts[$lines - 1] -eq '') { $lines-- }
           if ($lines -gt 500) { $script:over++; Write-Output ($lines.ToString() + ' ' + $item.FullName) }
          elseif ($lines -ge 451) { Write-Output ('WATCH ' + $lines.ToString() + ' ' + $item.FullName) }
         }
       }
     }
     $canon = @(@('src','app','apps','packages','components','lib','workers') | Where-Object { Test-Path -LiteralPath $_ -PathType Container })
     if ($canon.Count -gt 0) {
       foreach ($d in ($canon + @('scripts','tests','skills') | Select-Object -Unique)) { Walk $d ($d -eq 'skills') }
     } else {
       foreach ($top in (Get-ChildItem -LiteralPath '.' -Directory)) {
         if (-not $top.Name.StartsWith('.') -and ($skip -notcontains $top.Name) -and -not ($top.Attributes -band [System.IO.FileAttributes]::ReparsePoint)) { Walk $top.FullName ($top.Name -eq 'skills') }
       }
     }
     Write-Output ('SCAN_OK scanned=' + $n + ' over500=' + $over)
     \`\`\``

const SCAN_METHOD_2 = `     \`\`\`javascript
import {readdirSync as r,lstatSync as s,readFileSync as f} from 'fs';import {join as j} from 'path';const skip=new Set(['.git','vendor','third_party','node_modules','dist','coverage','build','.next','out','.wrangler','.turbo','.output','.svelte-kit','.test-output']);let n=0,over=0;function w(d,sk=false){const st0=s(d,{throwIfNoEntry:false});if(!st0||st0.isSymbolicLink()||!st0.isDirectory())return;const inS=sk||d==='skills'||/(?:^|[\\\\/])skills$/.test(d);for(const x of r(d)){if(skip.has(x))continue;const p=j(d,x);const st=s(p,{throwIfNoEntry:false});if(!st||st.isSymbolicLink())continue;if(st.isDirectory())w(p,inS);else if((/\\.(ts|tsx|js|mjs|cjs)$/.test(x)||(inS&&/\\.md$/.test(x)))&&!/\\.(test|spec|bench)\\./.test(x)&&!/\\.d\\.ts$/.test(x)){n++;const parts=f(p,'utf8').split(/\\r?\\n/);const l=parts.length>0&&parts[parts.length-1]===''?parts.length-1:parts.length;if(l>500){over++;console.log(l,p)}else if(l>=451)console.log('WATCH',l,p)}}}const canon=['src','app','apps','packages','components','lib','workers'].filter(d=>{const st=s(d,{throwIfNoEntry:false});return Boolean(st&&!st.isSymbolicLink()&&st.isDirectory())});if(canon.length>0){for(const d of new Set([...canon,'scripts','tests','skills']))w(d,d==='skills');}else{for(const top of r('.')){if(!top.startsWith('.')&&!skip.has(top)){const st=s(top,{throwIfNoEntry:false});if(st&&!st.isSymbolicLink()&&st.isDirectory())w(top,top==='skills');}}}console.log('SCAN_OK scanned='+n+' over500='+over);
     \`\`\``

const TEMP_SCRIPT_RULE =
    "write the script to a temporary `.mjs` file in the session's scratch/temp directory outside the repository (parent-owned only — read-only subagents do not run shell scripts) and run `node <file>` (or `bun <file>` in Bun-only repositories) with the repository as the working directory (never an inline `-e` here-string, which Windows execution proxies rewrite). Note for Antigravity Plan Mode: if `write_file` is blocked while Plan Mode is active, write the scratch `.mjs` file inside `run_command` using a single-quoted PowerShell here-string (`$code = @'\\n...\\n'@; [System.IO.File]::WriteAllText($scratchFile, $code, [System.Text.UTF8Encoding]::new($false))`) so PowerShell never interpolates `$` tokens in JavaScript or writes a UTF-8 BOM, and propagate `$LASTEXITCODE` across cleanup (`$ec = 0; try { node $scratchFile; $ec = $LASTEXITCODE } finally { Remove-Item -LiteralPath $scratchFile -Force -ErrorAction SilentlyContinue }; if ($ec -ne 0) { exit $ec }`) so `Remove-Item` never masks failures"

